import time

import z3


# ---------------------------------------------------------------------------
# 1. AST classes
# ---------------------------------------------------------------------------

class Variable:
    """Program variable reference."""

    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return f"Variable({self.name})"


class Const:
    """Integer constant."""

    def __init__(self, value):
        self.value = int(value)

    def __repr__(self):
        return f"Const({self.value})"


class BinOp:
    """Binary operation (+, -, *, <, <=, ==, !=, >, >=, and, or).

    The parser also produces unary ``not`` as BinOp('not', expr, None).
    """

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinOp({self.op}, {self.left}, {self.right})"


class Assign:
    """Variable assignment."""

    def __init__(self, var_name, expr):
        self.var_name = var_name
        self.expr = expr

    def __repr__(self):
        return f"Assign({self.var_name}, {self.expr})"


class If:
    """Conditional branch."""

    def __init__(self, cond, then_body, else_body):
        self.cond = cond
        self.then_body = then_body
        self.else_body = else_body

    def __repr__(self):
        return f"If({self.cond}, {self.then_body}, {self.else_body})"


class While:
    """Bounded while loop with (optional) iteration bound annotation."""

    def __init__(self, cond, body, bound=None):
        self.cond = cond
        self.body = body
        self.bound = bound

    def __repr__(self):
        return f"While({self.cond}, {self.body}, bound={self.bound})"


class Assert:
    """Assertion to verify."""

    def __init__(self, cond):
        self.cond = cond

    def __repr__(self):
        return f"Assert({self.cond})"


class Sequence:
    """Sequential composition of statements."""

    def __init__(self, stmts):
        self.stmts = list(stmts)

    def __repr__(self):
        return f"Sequence({self.stmts})"


# ---------------------------------------------------------------------------
# 2. Recursive-descent parser
# ---------------------------------------------------------------------------

_KEYWORDS = {"var", "if", "else", "while", "assert", "and", "or", "not", "bound"}
_MULTI_OPS = ("<=", "==", "!=", ">=", "//")
_SINGLE = set("+-*<>=(){};!")


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind, value):
        self.kind = kind
        self.value = value

    def __repr__(self):
        return f"<{self.kind}:{self.value}>"


def _tokenize(text):
    tokens = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if text.startswith("//", i):  # line comment
            j = text.find("\n", i)
            i = n if j == -1 else j + 1
            continue
        if c.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(_Token("num", int(text[i:j])))
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            tokens.append(_Token("kw" if word in _KEYWORDS else "ident", word))
            i = j
            continue
        two = text[i:i + 2]
        if two in ("<=", "==", "!=", ">="):
            tokens.append(_Token("op", two))
            i += 2
            continue
        if c in _SINGLE:
            kind = "op" if c in "+-*<>=!" else "punct"
            tokens.append(_Token(kind, c))
            i += 1
            continue
        raise SyntaxError(f"unexpected character {c!r} at position {i}")
    tokens.append(_Token("eof", ""))
    return tokens


class _Parser:
    """Recursive-descent parser for the simple imperative language.

    Grammar:
        program   := stmt*
        stmt      := 'var' IDENT '=' expr ';'
                   | IDENT '=' expr ';'
                   | 'if' '(' expr ')' block ('else' block)?
                   | 'while' '(' expr ')' bound? block
                   | 'assert' '(' expr ')' ';'
        block     := '{' stmt* '}'
        bound     := 'bound' ( NUM | '(' NUM ')' )
        expr      := or_expr
        or_expr   := and_expr ('or' and_expr)*
        and_expr  := not_expr ('and' not_expr)*
        not_expr  := 'not' not_expr | cmp_expr
        cmp_expr  := add_expr (('<'|'<='|'=='|'!='|'>'|'>=') add_expr)?
        add_expr  := mul_expr (('+'|'-') mul_expr)*
        mul_expr  := unary ('*' unary)*
        unary     := '-' unary | atom
        atom      := NUM | IDENT | '(' expr ')'
    """

    def __init__(self, text):
        self.tokens = _tokenize(text)
        self.pos = 0

    # -- token helpers -----------------------------------------------------
    def peek(self):
        return self.tokens[self.pos]

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, value):
        tok = self.next()
        if tok.value != value:
            raise SyntaxError(f"expected {value!r}, got {tok.value!r}")
        return tok

    # -- statements ----------------------------------------------------------
    def parse_program(self):
        stmts = []
        while self.peek().kind != "eof":
            stmts.append(self.parse_stmt())
        if len(stmts) == 1:
            return stmts[0]
        return Sequence(stmts)

    def parse_stmt(self):
        tok = self.peek()
        if tok.value == "var":
            self.next()
            name = self.next().value
            self.expect("=")
            expr = self.parse_expr()
            self.expect(";")
            return Assign(name, expr)
        if tok.value == "assert":
            self.next()
            self.expect("(")
            cond = self.parse_expr()
            self.expect(")")
            self.expect(";")
            return Assert(cond)
        if tok.value == "if":
            self.next()
            self.expect("(")
            cond = self.parse_expr()
            self.expect(")")
            then_body = self.parse_block()
            else_body = None
            if self.peek().value == "else":
                self.next()
                else_body = self.parse_block()
            return If(cond, then_body, else_body)
        if tok.value == "while":
            self.next()
            self.expect("(")
            cond = self.parse_expr()
            self.expect(")")
            bound = None
            if self.peek().value == "bound":
                self.next()
                if self.peek().value == "(":
                    self.next()
                    bound = self.next().value
                    self.expect(")")
                else:
                    bound = self.next().value
            body = self.parse_block()
            return While(cond, body, bound)
        if tok.kind == "ident":
            name = self.next().value
            self.expect("=")
            expr = self.parse_expr()
            self.expect(";")
            return Assign(name, expr)
        raise SyntaxError(f"unexpected token {tok!r}")

    def parse_block(self):
        self.expect("{")
        stmts = []
        while self.peek().value != "}":
            stmts.append(self.parse_stmt())
        self.expect("}")
        if len(stmts) == 1:
            return stmts[0]
        return Sequence(stmts)

    # -- expressions ---------------------------------------------------------
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek().value == "or":
            self.next()
            left = BinOp("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek().value == "and":
            self.next()
            left = BinOp("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.peek().value == "not":
            self.next()
            return BinOp("not", self.parse_not(), None)
        if self.peek().value == "!":
            self.next()
            return BinOp("not", self.parse_not(), None)
        return self.parse_cmp()

    def parse_cmp(self):
        left = self.parse_add()
        if self.peek().value in ("<", "<=", "==", "!=", ">", ">="):
            op = self.next().value
            return BinOp(op, left, self.parse_add())
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.peek().value in ("+", "-"):
            op = self.next().value
            left = BinOp(op, left, self.parse_mul())
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.peek().value == "*":
            self.next()
            left = BinOp("*", left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.peek().value == "-":
            self.next()
            return BinOp("-", Const(0), self.parse_unary())
        return self.parse_atom()

    def parse_atom(self):
        tok = self.next()
        if tok.kind == "num":
            return Const(tok.value)
        if tok.kind == "ident":
            return Variable(tok.value)
        if tok.value == "(":
            expr = self.parse_expr()
            self.expect(")")
            return expr
        raise SyntaxError(f"unexpected token {tok!r}")


def parse_program(text):
    """Parse program text into an AST."""
    return _Parser(text).parse_program()


# ---------------------------------------------------------------------------
# 3. Horn clause encoding
# ---------------------------------------------------------------------------

class HornClause:
    """A single constrained Horn clause.

    body_rel(vars) ∧ constraint(vars) ∧ updates → head_rel(vars')

    - head: name of the head relation (None for query/error clauses)
    - body: name of the body relation (None for facts)
    - constraint: AST expression over the current state (or None)
    - updates: dict var_name -> AST expression for the next state
    - is_query: True if this clause is a safety query (body ∧ ¬cond → Error)
    """

    def __init__(self, head, body=None, constraint=None, updates=None,
                 is_query=False):
        self.head = head
        self.body = body
        self.constraint = constraint
        self.updates = dict(updates) if updates else {}
        self.is_query = is_query

    def __repr__(self):
        if self.is_query:
            return f"HornClause(query: {self.body} ∧ ¬({self.constraint}) → Error)"
        return f"HornClause({self.body} → {self.head})"


def _collect_vars(node, acc):
    if isinstance(node, Assign):
        acc.add(node.var_name)
        _collect_vars(node.expr, acc)
    elif isinstance(node, Variable):
        acc.add(node.name)
    elif isinstance(node, BinOp):
        _collect_vars(node.left, acc)
        if node.right is not None:
            _collect_vars(node.right, acc)
    elif isinstance(node, Sequence):
        for s in node.stmts:
            _collect_vars(s, acc)
    elif isinstance(node, If):
        _collect_vars(node.cond, acc)
        _collect_vars(node.then_body, acc)
        if node.else_body is not None:
            _collect_vars(node.else_body, acc)
    elif isinstance(node, While):
        _collect_vars(node.cond, acc)
        _collect_vars(node.body, acc)
    elif isinstance(node, Assert):
        _collect_vars(node.cond, acc)


class HornEncoder:
    """Encodes imperative programs as constrained Horn clauses."""

    def __init__(self):
        self.clauses = []
        self.relations = []        # relation names in creation order
        self.loop_relations = []   # loop-head relation names
        self.program_vars = []
        self._counter = 0

    # -- helpers -------------------------------------------------------------
    def _fresh(self, prefix="loc"):
        name = f"{prefix}_{self._counter}"
        self._counter += 1
        self.relations.append(name)
        return name

    # -- main entry points -----------------------------------------------------
    def encode_program(self, ast):
        """Traverse AST, produce a list of HornClause objects."""
        self.clauses = []
        self.relations = []
        self.loop_relations = []
        self._counter = 0
        vars_found = set()
        _collect_vars(ast, vars_found)
        self.program_vars = sorted(vars_found)

        entry = self._fresh("entry")
        self.clauses.append(HornClause(head=entry))  # initial fact
        self._encode_stmt(ast, entry)
        return self.clauses

    def encode_assignment(self, assign, pre_rel, post_rel):
        """Clause: post-state equals pre-state with assigned variable updated."""
        clause = HornClause(head=post_rel, body=pre_rel,
                            updates={assign.var_name: assign.expr})
        self.clauses.append(clause)
        return clause

    def encode_loop(self, while_node, loop_rel):
        """Recursive Horn clause pair for a while loop.

        Creates: entry → loop head, loop head ∧ cond → body,
        body → loop head (recursive), loop head ∧ ¬cond → exit.
        Returns the exit relation name.
        """
        head = self._fresh("loop")
        self.loop_relations.append(head)
        # entry → loop_rel(init)
        self.clauses.append(HornClause(head=head, body=loop_rel))
        # loop_rel(x) ∧ cond → body_entry
        body_entry = self._fresh("loopbody")
        self.clauses.append(HornClause(head=body_entry, body=head,
                                       constraint=while_node.cond))
        # encode body, then loop back: body_end → loop_rel(x')
        body_end = self._encode_stmt(while_node.body, body_entry)
        self.clauses.append(HornClause(head=head, body=body_end))
        # loop_rel(x) ∧ ¬cond → exit
        exit_rel = self._fresh("loopexit")
        self.clauses.append(HornClause(
            head=exit_rel, body=head,
            constraint=BinOp("not", while_node.cond, None)))
        return exit_rel

    def encode_branch(self, if_node, pre_rel, post_rel):
        """Two paths: cond ∧ then_body, and ¬cond ∧ else_body."""
        # then path
        then_entry = self._fresh("then")
        self.clauses.append(HornClause(head=then_entry, body=pre_rel,
                                       constraint=if_node.cond))
        then_end = self._encode_stmt(if_node.then_body, then_entry)
        self.clauses.append(HornClause(head=post_rel, body=then_end))
        # else path
        else_entry = self._fresh("else")
        self.clauses.append(HornClause(
            head=else_entry, body=pre_rel,
            constraint=BinOp("not", if_node.cond, None)))
        if if_node.else_body is not None:
            else_end = self._encode_stmt(if_node.else_body, else_entry)
            self.clauses.append(HornClause(head=post_rel, body=else_end))
        else:
            self.clauses.append(HornClause(head=post_rel, body=else_entry))
        return post_rel

    def encode_assertion(self, assert_node, pre_rel):
        """Safety query: pre_rel(x) ∧ ¬assert_cond → Error."""
        clause = HornClause(head=None, body=pre_rel,
                            constraint=assert_node.cond, is_query=True)
        self.clauses.append(clause)
        return clause

    # -- internal statement dispatch -------------------------------------------
    def _encode_stmt(self, stmt, pre_rel):
        """Encode stmt starting from pre_rel; return the post relation name."""
        if isinstance(stmt, Assign):
            post = self._fresh("loc")
            self.encode_assignment(stmt, pre_rel, post)
            return post
        if isinstance(stmt, Sequence):
            rel = pre_rel
            for s in stmt.stmts:
                rel = self._encode_stmt(s, rel)
            return rel
        if isinstance(stmt, If):
            post = self._fresh("join")
            self.encode_branch(stmt, pre_rel, post)
            return post
        if isinstance(stmt, While):
            return self.encode_loop(stmt, pre_rel)
        if isinstance(stmt, Assert):
            self.encode_assertion(stmt, pre_rel)
            return pre_rel
        raise TypeError(f"cannot encode node {stmt!r}")

    # -- Z3 translation ----------------------------------------------------------
    def _expr_to_z3(self, expr, env):
        if isinstance(expr, Const):
            return expr.value
        if isinstance(expr, Variable):
            return env[expr.name]
        if isinstance(expr, BinOp):
            if expr.op == "not":
                return z3.Not(self._expr_to_z3(expr.left, env))
            left = self._expr_to_z3(expr.left, env)
            right = self._expr_to_z3(expr.right, env)
            if expr.op == "+":
                return left + right
            if expr.op == "-":
                return left - right
            if expr.op == "*":
                return left * right
            if expr.op == "<":
                return left < right
            if expr.op == "<=":
                return left <= right
            if expr.op == "==":
                return left == right
            if expr.op == "!=":
                return left != right
            if expr.op == ">":
                return left > right
            if expr.op == ">=":
                return left >= right
            if expr.op == "and":
                return z3.And(left, right)
            if expr.op == "or":
                return z3.Or(left, right)
            raise ValueError(f"unknown operator {expr.op!r}")
        raise TypeError(f"cannot translate expression {expr!r}")

    def to_z3(self, program_vars=None):
        """Convert all encoded clauses to Z3 Fixedpoint rules.

        Returns (fixedpoint, queries, relation_decls) where queries is a
        list of 0-arity error relations, one per assertion.
        """
        if program_vars is None:
            program_vars = self.program_vars
        n = len(program_vars)
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")

        sorts = [z3.IntSort()] * n
        decls = {}
        for name in self.relations:
            decl = z3.Function(name, *(sorts + [z3.BoolSort()]))
            fp.register_relation(decl)
            decls[name] = decl

        env = {v: z3.Int(f"{v}_c") for v in program_vars}      # current state
        env_p = {v: z3.Int(f"{v}_n") for v in program_vars}    # next state
        cur = [env[v] for v in program_vars]
        nxt = [env_p[v] for v in program_vars]

        queries = []
        for i, clause in enumerate(self.clauses):
            if clause.body is not None:
                body_expr = decls[clause.body](*cur)
            else:
                body_expr = z3.BoolVal(True)
            if clause.constraint is not None:
                cond = self._expr_to_z3(clause.constraint, env)
                if clause.is_query:
                    cond = z3.Not(cond)  # violation of the assertion
                body_expr = z3.And(body_expr, cond)
            if clause.is_query:
                err = z3.Function(f"error_{i}", z3.BoolSort())
                fp.register_relation(err)
                fp.add_rule(err(), body_expr)
                queries.append(err())
                continue
            frame = []
            for v in program_vars:
                if v in clause.updates:
                    frame.append(env_p[v] ==
                                 self._expr_to_z3(clause.updates[v], env))
                else:
                    frame.append(env_p[v] == env[v])
            if frame:
                body_expr = z3.And(body_expr, *frame)
                fp.add_rule(decls[clause.head](*nxt), body_expr)
            else:
                fp.add_rule(decls[clause.head](*cur), body_expr)
        return fp, queries, decls


# ---------------------------------------------------------------------------
# 4. Horn verifier
# ---------------------------------------------------------------------------

def verify_program(text, timeout_ms=10000):
    """Parse, encode, and verify a program with Z3's Spacer engine.

    Returns dict: {"safe": bool, "num_clauses": int, "num_relations": int}.
    """
    ast = parse_program(text)
    encoder = HornEncoder()
    clauses = encoder.encode_program(ast)
    fp, queries, _ = encoder.to_z3(encoder.program_vars)
    fp.set("timeout", timeout_ms)

    safe = True
    for q in queries:
        res = fp.query(q)
        if res == z3.sat:
            safe = False
            break
        if res == z3.unknown:
            raise RuntimeError("solver returned unknown")
    return {
        "safe": safe,
        "num_clauses": len(clauses),
        "num_relations": len(encoder.relations),
    }


# ---------------------------------------------------------------------------
# Module entry point: run the experiments
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    from verification.experiments.horn_exp import run_horn_experiments

    run_horn_experiments()

