"""Experiments for the imperative-to-Horn clause translator."""

import time

import z3

from framework.reporter import report_result
from verification.horn_translator import HornEncoder, parse_program

PROGRAMS = {
    "simple_counter": """
        var x = 0;
        while(x < 10) { x = x + 1; }
        assert(x == 10);
    """,
    "sum_accumulator": """
        var s = 0;
        var i = 0;
        while(i < 5) { s = s + i; i = i + 1; }
        assert(s >= 0);
    """,
    "branch_test": """
        var x = 5;
        if (x > 3) { x = x - 1; } else { x = x + 1; }
        assert(x >= 0);
    """,
    "unsafe_loop": """
        var x = 0;
        while(x < 100) { x = x + 2; }
        assert(x < 50);
    """,
    "nested_arithmetic": """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6);
    """,
}

SOLVER_TIMEOUT_MS = 10000


class HornTranslatorExperiment:
    """Translate and verify the 5 benchmark programs via Horn clauses."""

    def __init__(self, programs=None, timeout_ms=SOLVER_TIMEOUT_MS):
        self.programs = programs or PROGRAMS
        self.timeout_ms = timeout_ms
        self.results = {}  # name -> result dict

    def run_all(self):
        for name, text in self.programs.items():
            self.results[name] = self._verify_one(text)
        return self.results

    def _verify_one(self, text):
        start = time.perf_counter()
        ast = parse_program(text)
        encoder = HornEncoder()
        clauses = encoder.encode_program(ast)
        fp, queries, _ = encoder.to_z3(encoder.program_vars)
        translation_time = time.perf_counter() - start

        fp.set("timeout", self.timeout_ms)
        safe = True
        for q in queries:
            res = fp.query(q)
            if res == z3.sat:
                safe = False
                break
            if res == z3.unknown:
                raise RuntimeError("solver returned unknown")

        invariants = 0
        if safe and encoder.loop_relations:
            answer = fp.get_answer()
            answer_str = answer.sexpr() if answer is not None else ""
            for rel in encoder.loop_relations:
                if rel in answer_str:
                    invariants += 1

        return {
            "safe": safe,
            "num_clauses": len(clauses),
            "num_relations": len(encoder.relations),
            "num_loops": len(encoder.loop_relations),
            "loop_invariants": invariants,
            "translation_time": translation_time,
        }

    # -- individual metrics ----------------------------------------------------
    def clauses_generated(self):
        return sum(r["num_clauses"] for r in self.results.values())

    def programs_verified(self):
        return sum(1 for r in self.results.values() if r["safe"])

    def programs_unsafe(self):
        return sum(1 for r in self.results.values() if not r["safe"])

    def loop_invariants(self):
        return sum(r["loop_invariants"] for r in self.results.values())

    def translation_time(self):
        return round(sum(r["translation_time"] for r in self.results.values()), 2)


def run_horn_experiments():
    """Run all Horn translator experiments and report KEY: VALUE lines."""
    exp = HornTranslatorExperiment()
    exp.run_all()
    report_result("HORN_CLAUSES_GENERATED", exp.clauses_generated())
    report_result("HORN_PROGRAMS_VERIFIED", exp.programs_verified())
    report_result("HORN_PROGRAMS_UNSAFE", exp.programs_unsafe())
    report_result("HORN_LOOP_INVARIANTS", exp.loop_invariants())
    report_result("HORN_TRANSLATION_TIME", exp.translation_time())
    return exp.results


if __name__ == "__main__":
    run_horn_experiments()

